import type {
  RuntimeTranslationCatalog,
  TranslationCatalogEntry
} from '@/model/content/translation/TranslationCatalog'

export interface TranslationResolver {
  translate(id: string, source: string, context: string): string
}

export function translationSourceHash(source: string): string {
  let hash = 0x811c9dc5
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(16).padStart(8, '0')
}

export class TranslationSourceCollector implements TranslationResolver {
  readonly entries: Record<string, TranslationCatalogEntry> = {}

  translate(id: string, source: string, context: string): string {
    if (!source) return source
    if (this.entries[id]) throw new Error(`Duplicate translation id: ${id}`)
    this.entries[id] = {
      source,
      translation: source,
      context,
      sourceHash: translationSourceHash(source)
    }
    return source
  }
}

export class CatalogTranslationResolver implements TranslationResolver {
  constructor(private catalog: RuntimeTranslationCatalog) {
  }

  translate(id: string, source: string): string {
    if (!source) return source
    const translation = this.catalog.entries[id]
    if (!translation) throw new Error(`Locale ${this.catalog.targetLocale} is missing translation: ${id}`)
    if (!translation.trim()) {
      throw new Error(`Locale ${this.catalog.targetLocale} has an empty translation: ${id}`)
    }
    return translation
  }
}
