import Vue from 'vue'
import {LazyGetter} from 'lazy-get-decorator'
import {mainApp} from '@/main'
import {isDarkMode} from '@/cs/extensions/CSLang'
import {ProfileData} from '@/model/Data/ProfileData'
import {ProjectsData} from '@/model/Data/ProjectsData'
import {SolutionsData} from '@/model/Data/SolutionsData'
import {CVData} from '@/model/Data/CVData'
import {Locale} from '@/model/content/Locale'
import {createCV, createProfile, createProjects, createSolutions} from '@/model/content/createContent'

export class Model {

  isDarkMode = Vue.observable({value: isDarkMode()})

  private systemTheme: MediaQueryList | null = null

  constructor() {
    // Attach the listener at module init so a scheme change/settling that
    // happens between bundle evaluation and app mount is never lost.
    this.systemTheme = window.matchMedia('(prefers-color-scheme: dark)')
    this.systemTheme.addEventListener('change', this.systemThemeChanged)
  }

  followSystemTheme() {
    // Re-read immediately before mount to correct any race with module init.
    if (this.systemTheme) this.isDarkMode.value = this.systemTheme.matches
  }

  private systemThemeChanged = (event: MediaQueryListEvent) => {
    this.isDarkMode.value = event.matches
    // A change before the app starts is picked up by the mount sequence itself.
    if (!mainApp()) return
    this.loadThemeColors()
    mainApp().$forceUpdate()
  }

  @LazyGetter()
  get baseUrl() {
    return window.location.protocol + '//' + window.location.host
  }

  @LazyGetter()
  get isProduction() {
    return process.env.NODE_ENV === 'production'
  }

  @LazyGetter()
  get projects(): ProjectsData {
    return createProjects(Locale.active)
  }

  @LazyGetter()
  get profile(): ProfileData {
    return createProfile(Locale.active, this.projects)
  }

  @LazyGetter()
  get solutions(): SolutionsData {
    return createSolutions(Locale.active, this.projects)
  }

  @LazyGetter()
  get cv(): CVData {
    return createCV(Locale.active, this.profile, this.projects)
  }

  loadThemeColors() {
    const primary = this.themeColor('--primary-color')
    // The compatibility CSS consumes this derived shade before mount. Validate
    // it with the runtime palette contract even though Vuetify derives it itself.
    this.themeColor('--primary-lighten-1-color')
    const secondary = this.themeColor('--secondary-color')
    const accent = this.themeColor('--accent-color')
    mainApp().$vuetify.theme.primary = primary
    mainApp().$vuetify.theme.secondary = secondary
    mainApp().$vuetify.theme.accent = accent
  }

  private themeColor(property: string) {
    const value = getComputedStyle(document.documentElement).getPropertyValue(property).trim()
    if (!value) throw new Error(`Missing required CSS theme variable ${property}`)
    return value
  }

}

export default new Model()
