export class CVData {
  readonly sectionOrder = sectionOrder
  readonly selectedExperienceIds: readonly SelectedResumeExperienceId[] = selectedResumeExperienceIds
  readonly downloadUrl: string
  readonly downloadName: string

  private content: CVLocalizedContent = englishCVContent

  constructor(
    private profile: ProfileData,
    private projects: ProjectsData,
    locale: Locale
  ) {
    this.downloadUrl = `${Routes.cvPath}/rene-dohan-cv-${locale}.pdf`
    this.downloadName = `Rene-Dohan-CV-${locale.toUpperCase()}.pdf`
    this.assertValidRelationships()
  }

  setLocalizedContent(content: CVLocalizedContent) {
    this.content = content
    this.assertValidRelationships()
    return this
  }

  get photo() {
    return {src: this.profile.profileImages[0], alt: this.profile.profileImageAlts[0]}
  }

  get location() { return this.content.location }
  get specialisms() { return this.content.specialisms }
  get printContacts(): CVPrintContact[] {
    return [
      {id: CVContactIds.email, label: this.content.contactLabels[CVContactIds.email], value: 'dohan.rene@gmail.com', url: 'mailto:dohan.rene@gmail.com'},
      {id: CVContactIds.whatsapp, label: this.content.contactLabels[CVContactIds.whatsapp], value: '+62 821 4784 2109', url: 'https://wa.me/6282147842109'},
      {id: CVContactIds.linkedIn, label: this.content.contactLabels[CVContactIds.linkedIn], value: 'linkedin.com/in/renetik', url: 'https://www.linkedin.com/in/renetik'},
      {id: CVContactIds.website, label: this.content.contactLabels[CVContactIds.website], value: 'www.renetik.com', url: 'https://www.renetik.com'}
    ]
  }
  get summary() { return this.content.summary }
  get summaryTitle() { return this.content.summaryTitle }
  get impactTitle() { return this.content.impactTitle }
  get skillsTitle() { return this.content.skillsTitle }
  get experienceTitle() { return this.content.experienceTitle }
  get flagshipTitle() { return this.content.flagshipTitle }
  get earlierExperienceTitle() { return this.content.earlierExperienceTitle }
  get educationTitle() { return this.content.educationTitle }
  get downloadPdfTitle() { return this.content.downloadPdfTitle }
  get openPrintableTitle() { return this.content.openPrintableTitle }
  get completeExperienceTitle() { return this.content.completeExperienceTitle }
  get completeExperiencePrompt() { return this.content.completeExperiencePrompt }
  get printButtonTitle() { return this.content.printButtonTitle }
  get cvPageButtonTitle() { return this.content.cvPageButtonTitle }

  get impactHighlights() {
    return impactOrder.map(id => ({id, text: this.content.impactHighlights[id]}))
  }

  get skills(): CVSkillGroup[] {
    return skillGroupOrder.map(id => ({id, ...this.content.skillGroups[id]}))
  }

  get selectedExperience(): CVResumeExperience[] {
    const experienceById = this.experienceById()
    return this.selectedExperienceIds.map(id => {
      const experience = experienceById.get(id)!
      const copy = this.content.experience[id]
      return {
        ...experience,
        resumeTitle: copy.title,
        resumeBullets: copy.bullets,
        resumeTechnologies: copy.technologies,
        links: this.resolveLinks(copy.relatedRoutes || [])
      }
    })
  }

  get flagshipProjects(): CVFlagshipProject[] {
    const experienceById = this.experienceById()
    return flagshipOrder.map(id => {
      const copy = this.content.flagshipProjects[id]
      const experience = experienceById.get(ExperienceIds.renetikMusicApps)!
      return {
        id,
        title: copy.title,
        role: copy.role,
        date: experience.date,
        bullets: copy.bullets,
        technologies: copy.technologies,
        links: [
          {label: copy.websiteLabel, url: 'https://renetik.com/app/', external: true},
          ...this.resolveLinks([ProjectRoutes.renetikMusicApps])
        ]
      }
    })
  }

  get earlierExperience(): CVEarlierExperience[] {
    const experienceById = this.experienceById()
    return earlierExperienceOrder.map(id => {
      const experienceIds = earlierExperienceDefinitions[id]
      const experiences = experienceIds.map(experienceId => experienceById.get(experienceId)!)
      const firstYear = Math.min(...experiences.map(item => item.startYear))
      const lastYear = Math.max(...experiences.map(item => item.endYear || item.startYear))
      return {
        id,
        ...this.content.earlierExperience[id],
        date: `${firstYear} – ${lastYear}`,
        experienceIds
      }
    })
  }

  get education(): EducationDisplay {
    return this.profile.education[0]
  }

  assertValidRelationships() {
    this.assertUnique('selected experience', this.selectedExperienceIds)
    this.assertUnique('resume sections', this.sectionOrder)
    this.assertUnique('impact highlights', impactOrder)
    this.assertUnique('skill groups', skillGroupOrder)

    const experienceById = this.experienceById()
    const referencedExperienceIds: ExperienceId[] = [
      ...this.selectedExperienceIds,
      ExperienceIds.renetikMusicApps,
      ...Object.values(earlierExperienceDefinitions).reduce<ExperienceId[]>((all, ids) => all.concat(ids), [])
    ]
    referencedExperienceIds.forEach(id => {
      if (!experienceById.has(id)) throw new Error(`CV references unresolved experience: ${id}`)
    })

    Object.values(this.content.experience).forEach(copy => {
      (copy.relatedRoutes || []).forEach(route => this.projects.require(route))
    })
  }

  private experienceById() {
    return new Map(this.profile.experience.map(item => [item.id, item]))
  }

  private resolveLinks(routes: ProjectRoute[]): CVResumeLink[] {
    return routes.map(route => ({
      label: `${this.content.projectLinkTitle}: ${this.projects.require(route).title}`,
      url: Routes.projectPath(route),
      external: false
    }))
  }

  private assertUnique(label: string, ids: readonly string[]) {
    if (new Set(ids).size !== ids.length) throw new Error(`CV contains duplicate ${label}`)
  }
}
