import type {SeoContent, UiContent} from '@/model/content/Schema'
import type {TranslationResolver} from '@/model/content/translation/TranslationResolver'

export function translateUiContent(source: UiContent, resolver: TranslationResolver): UiContent {
  const translated = {...source}
  for (const key of Object.keys(source) as Array<keyof UiContent>) {
    translated[key] = resolver.translate(`ui.${key}`, source[key], `Portal interface: ${key}`)
  }
  return translated
}

export function translateSeoContent(source: SeoContent, resolver: TranslationResolver): SeoContent {
  return {
    siteName: resolver.translate('seo.siteName', source.siteName, 'Website name used in metadata'),
    defaultTitle: resolver.translate('seo.defaultTitle', source.defaultTitle, 'Default browser and search-result title'),
    screenshotSuffix: resolver.translate('seo.screenshotSuffix', source.screenshotSuffix, 'Suffix used in generated image descriptions'),
    ogLocale: source.ogLocale
  }
}
