import type {ProjectData} from '@/model/Data/ProjectData'
import type {ProfileData} from '@/model/Data/ProfileData'
import Routes from '@/model/Routes'
import {brandLogoPath, brandName, socialHandle} from '@/model/Brand'
import {activeSeo, activeUi, ogLocaleFor} from '@/model/content/active'
import {Locale, neutralPath} from '@/model/content/Locale'
import type {Locale as LocaleCode} from '@/model/content/Schema'
import {locales} from '@/model/content/Schema'

export const canonicalOrigin = 'https://renetik.com'

export function defaultTitle() {
  return activeSeo().defaultTitle
}

export function canonicalUrl(path: string = '/', locale: LocaleCode = Locale.active) {
  const localizedPath = Locale.pathFor(locale, path)
  const canonicalPath = localizedPath === '/' || localizedPath.endsWith('/') || /\.[^/]+$/.test(localizedPath)
    ? localizedPath
    : `${localizedPath}/`
  return `${canonicalOrigin}${canonicalPath}`
}

/**
 * Generated 1200x630 share card for a services page, written by
 * `scripts/generate-og-images.mjs`. Pages whose own media already previews well
 * — project pages with real screenshots — keep their hero image instead.
 */
export function socialCardPath(path: string, locale: LocaleCode = Locale.active) {
  const localizedPath = Locale.pathFor(locale, path).replace(/\/+$/, '')
  const isHome = neutralPath(path) === '/'
  return `/og${localizedPath}${isHome ? '/index' : ''}.jpg?v=2`
}

export function absoluteAssetUrl(path: string) {
  if (path.startsWith('http://') || path.startsWith('https://')) return path
  return `${canonicalOrigin}${path.startsWith('/') ? path : `/${path}`}`
}

export function stripHtml(value: unknown): string {
  return String(value == null ? '' : value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim()
}

export function truncateText(value: string, maxLength = 160) {
  if (value.length <= maxLength) return value
  const trimmed = value.slice(0, maxLength - 1).trim()
  const lastSpace = trimmed.lastIndexOf(' ')
  return `${trimmed.slice(0, lastSpace > 80 ? lastSpace : trimmed.length)}...`
}

export function descriptionFrom(value: unknown) {
  return truncateText(stripHtml(value))
}

/**
 * Services pages sign with the person; the gateway signs with the brand that
 * owns both properties behind it, so the suffix is overridable per page.
 */
function titleSignature(brand: string) {
  return brand.split(/\s+[—|]\s+/)[0].trim()
}

function conciseTitle(title: string, signature: string) {
  const firstClause = title.split(/\s+[—|]\s+/)[0]
  return firstClause.replace(signature, '').replace(/\s+/g, ' ').trim() || firstClause
}

export function fullTitle(title: string, brand: string = activeSeo().siteName) {
  if (!title) return defaultTitle()
  const signature = titleSignature(brand)
  return `${conciseTitle(title, signature)} | ${signature}`
}

/**
 * The one Person node every page points at, so search engines resolve the whole
 * site to a single entity instead of one per page. Defined on the introduction
 * page, which carries the full profile. The `@id` is pinned to the locale-neutral
 * English URL so ten localized pages all reference the same Person instead of
 * minting ten that no consumer can merge; `url` fields elsewhere stay localized.
 */
export function personId() {
  return `${canonicalUrl(Routes.introductionPath, 'en')}#person`
}

export function personReference() {
  return {'@id': personId()}
}

/**
 * The Organization node — the Renetik *živnosť* (sole proprietorship) — defined
 * on the gateway, the brand's root page. Locale-neutral `@id` for the same
 * reason as the Person: one resolvable entity across every localized gateway.
 */
export function organizationId() {
  return `${canonicalOrigin}/#organization`
}

export function organizationReference() {
  return {'@id': organizationId()}
}

/** The single WebSite node for renetik.com, owned by the gateway. */
export function websiteId() {
  return `${canonicalOrigin}/#website`
}

/**
 * Google parses structured data per page, so a bare `{'@id': '…#person'}` on a
 * page that never defines the node is an unresolved reference. These compact
 * stubs carry the same `@id` as the canonical node plus just enough fields to
 * stay self-describing, so the entities still consolidate across pages.
 */
export function personStub(profile: ProfileData) {
  return {
    ...personReference(),
    '@type': 'Person',
    name: stripHtml(profile.name),
    url: canonicalUrl(Routes.introductionPath, 'en')
  }
}

export function organizationStub() {
  return {
    ...organizationReference(),
    '@type': 'Organization',
    name: brandName,
    url: canonicalOrigin
  }
}

/**
 * The Renetik Organization — the registered Slovak sole proprietorship (*živnosť*)
 * behind the brand, with René as founder and owner. Same facts are operator-
 * supplied and public; nothing here is invented. Brand profiles only in `sameAs`
 * (the person's professional profiles live on the Person); the Messenger deep link
 * is a chat action, not a profile page, so it is filtered out.
 */
export function organizationNode(profile: ProfileData) {
  const brandSameAs = profile.socialLinks
    .filter(link => !link.url.startsWith('https://m.me/'))
    .map(link => link.url)
    .concat([
      'https://play.google.com/store/apps/dev?id=7192732930930877763',
      'https://github.com/renetik'
    ])
  return {
    '@type': 'Organization',
    '@id': organizationId(),
    name: brandName,
    legalName: 'René Doháň',
    url: canonicalOrigin,
    logo: absoluteAssetUrl(brandLogoPath),
    description: activeUi().gatewaySeoDescription,
    founder: personReference(),
    owner: personReference(),
    foundingDate: '2006-05-17',
    address: {
      '@type': 'PostalAddress',
      streetAddress: 'Čiližská 5001/1',
      addressLocality: 'Bratislava',
      postalCode: '82107',
      addressCountry: 'SK'
    },
    areaServed: {'@type': 'Place', name: 'Worldwide'},
    knowsLanguage: ['en', 'sk'],
    taxID: '1076186067',
    vatID: 'SK1076186067',
    identifier: '43162649',
    sameAs: brandSameAs
  }
}

/** Generated share cards; declaring their size lets scrapers render without fetching first. */
export const socialCardWidth = 1200
export const socialCardHeight = 630

export function pageMetaInfo(
  title: string,
  description: string,
  path: string,
  image: string,
  structuredData?: Record<string, unknown>,
  brand: string = activeSeo().siteName
): any {
  const fullPageTitle = fullTitle(title, brand)
  const url = canonicalUrl(path)
  const imageUrl = absoluteAssetUrl(image)
  const isSocialCard = image.startsWith('/og/')
  const meta = [
    {vmid: 'description', name: 'description', content: description},
    {vmid: 'og:site_name', property: 'og:site_name', content: brand},
    {vmid: 'og:title', property: 'og:title', content: fullPageTitle},
    {vmid: 'og:description', property: 'og:description', content: description},
    {vmid: 'og:image', property: 'og:image', content: imageUrl},
    {vmid: 'og:image:alt', property: 'og:image:alt', content: fullPageTitle},
    ...(isSocialCard ? [
      {vmid: 'og:image:type', property: 'og:image:type', content: 'image/jpeg'},
      {vmid: 'og:image:width', property: 'og:image:width', content: String(socialCardWidth)},
      {vmid: 'og:image:height', property: 'og:image:height', content: String(socialCardHeight)}
    ] : []),
    {vmid: 'og:url', property: 'og:url', content: url},
    {vmid: 'og:type', property: 'og:type', content: 'website'},
    {vmid: 'og:locale', property: 'og:locale', content: activeSeo().ogLocale},
    ...locales.filter(locale => locale !== Locale.active).map(locale => ({
      vmid: `og:locale:alternate-${locale}`,
      property: 'og:locale:alternate',
      content: ogLocaleFor(locale)
    })),
    {vmid: 'twitter:card', name: 'twitter:card', content: 'summary_large_image'},
    {vmid: 'twitter:site', name: 'twitter:site', content: socialHandle},
    {vmid: 'twitter:creator', name: 'twitter:creator', content: socialHandle},
    {vmid: 'twitter:title', name: 'twitter:title', content: fullPageTitle},
    {vmid: 'twitter:description', name: 'twitter:description', content: description},
    {vmid: 'twitter:image', name: 'twitter:image', content: imageUrl},
    {vmid: 'twitter:image:alt', name: 'twitter:image:alt', content: fullPageTitle}
  ]
  const metaInfo: any = {
    title,
    // The root template in main.ts signs every title with the site name, so a
    // page on another brand has to replace the template, not just the chunk.
    ...(brand === activeSeo().siteName ? {} : {titleTemplate: () => fullPageTitle}),
    meta,
    link: [
      {vmid: 'canonical', rel: 'canonical', href: url},
      ...locales.map(locale => ({vmid: `alternate-${locale}`, rel: 'alternate', hreflang: locale, href: canonicalUrl(path, locale)})),
      {vmid: 'alternate-default', rel: 'alternate', hreflang: 'x-default', href: canonicalUrl(path, 'en')}
    ]
  }
  if (structuredData) {
    metaInfo.script = [
      {vmid: 'jsonld', type: 'application/ld+json', json: structuredData}
    ]
  }
  return metaInfo
}

export function projectPath(project: ProjectData) {
  return Routes.projectPath(project.route)
}

/** Below this a subtitle alone wastes most of the search snippet, so detail is appended. */
const thinDescriptionLength = 110

export function projectDescription(project: ProjectData) {
  const subtitle = stripHtml(project.subtitle)
  if (subtitle.length >= thinDescriptionLength) return truncateText(subtitle)
  const detail = stripHtml(project.contribution || project.paragraphs[0] || '')
  return truncateText([subtitle, detail].filter(Boolean).join(' '))
}

export function imageAltForTitle(title: unknown, index?: number) {
  const cleanTitle = stripHtml(title)
  return index == null ? cleanTitle : `${cleanTitle} ${activeSeo().screenshotSuffix} ${index + 1}`
}

export function projectImageAlt(project: ProjectData, index?: number) {
  return imageAltForTitle(project.title, index)
}

/**
 * A `BreadcrumbList` node for schema-only breadcrumbs (no visible UI). Each item
 * resolves to its active-locale URL, since the breadcrumb describes this page's
 * place in the hierarchy the visitor is actually on.
 */
export function breadcrumbList(items: {name: string; path: string}[]) {
  return {
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: stripHtml(item.name),
      item: canonicalUrl(item.path)
    }))
  }
}
