import type {EngagementPeriod, Locale, PartialDate} from '@/model/content/Schema'

const intlLocale: Readonly<Record<string, string>> = {
  en: 'en-US'
}

/**
 * Format a single partial date. Year-only values render as the bare year;
 * year-month values render a localized long month plus year ("December 2023"
 * in English, "december 2023" in Slovak). The UTC construction keeps a
 * year-month value from shifting to the previous month in negative timezones.
 */
export function formatPartialDate(date: PartialDate, locale: Locale): string {
  if (date.month == null) return String(date.year)
  const value = new Date(Date.UTC(date.year, date.month - 1, 1))
  return new Intl.DateTimeFormat(intlLocale[locale] || locale, {
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC'
  }).format(value)
}

export interface DateRangeOptions {
  presentLabel: string
  separator?: string
}

/**
 * Format a start/end range. `isCurrent` uses the localized present label in
 * place of an end date; a missing end date with no `isCurrent` renders the
 * start alone (single-date entries such as a one-year role).
 */
export function formatDateRange(
  start: PartialDate,
  end: PartialDate | undefined,
  isCurrent: boolean | undefined,
  locale: Locale,
  options: DateRangeOptions
): string {
  const separator = options.separator ?? ' – '
  const startText = formatPartialDate(start, locale)
  if (isCurrent) return `${startText}${separator}${options.presentLabel}`
  if (!end) return startText
  return `${startText}${separator}${formatPartialDate(end, locale)}`
}

/**
 * Compact year range used for project display dates, wrapped in parentheses
 * (the parentheses are presentation, not data). Same-year ranges collapse to a
 * single year.
 */
export function formatProjectDate(
  start: PartialDate,
  end: PartialDate | undefined,
  isCurrent: boolean | undefined,
  locale: Locale,
  options: DateRangeOptions
): string {
  const separator = options.separator ?? ' – '
  if (isCurrent) return `(${start.year}${separator}${options.presentLabel})`
  if (!end || end.year === start.year) return `(${start.year})`
  return `(${start.year}${separator}${end.year})`
}

/** Format every interval without implying continuity between separate periods. */
export function formatEngagementPeriods(
  periods: EngagementPeriod[],
  locale: Locale,
  options: DateRangeOptions
): string {
  return periods
    .map(period => formatDateRange(
      period.startDate,
      period.endDate,
      period.isCurrent,
      locale,
      options
    ))
    .join('; ')
}

/** Compact project-card form of {@link formatEngagementPeriods}. */
export function formatProjectPeriods(
  periods: EngagementPeriod[],
  locale: Locale,
  options: DateRangeOptions
): string {
  const separator = options.separator ?? ' – '
  const ranges = periods.map(period => {
    if (period.isCurrent) return `${period.startDate.year}${separator}${options.presentLabel}`
    if (!period.endDate || period.endDate.year === period.startDate.year) return `${period.startDate.year}`
    return `${period.startDate.year}${separator}${period.endDate.year}`
  })
  return `(${ranges.join('; ')})`
}

/**
 * ISO 8601 form of a partial date: the bare year when only year precision is
 * known, otherwise `YYYY-MM`. Schema.org accepts both for `datePublished` and
 * related fields, and this is the same shape `temporalCoverage` emits.
 */
export function isoDate(date: PartialDate): string {
  return date.month == null
    ? String(date.year)
    : `${date.year}-${String(date.month).padStart(2, '0')}`
}

/** ISO-like intervals suitable for schema.org temporalCoverage. */
export function temporalCoverage(periods: EngagementPeriod[]): string[] {
  return periods.map(period => {
    const start = isoDate(period.startDate)
    if (period.isCurrent) return `${start}/..`
    return `${start}/${isoDate(period.endDate || period.startDate)}`
  })
}
