import {CVData} from '@/model/Data/CVData'
import {ProjectsData} from '@/model/Data/ProjectsData'
import {ProfileData} from '@/model/Data/ProfileData'
import {SolutionsData} from '@/model/Data/SolutionsData'
import {englishContent} from '@/model/content/locales/en'
import type {Locale} from '@/model/content/Schema'
import {generatedLocalizedContent} from '@/model/content/translation/GeneratedLocalizedContent'

export function contentFor(locale: Locale) {
  const generated = generatedLocalizedContent(locale)
  if (generated) return generated
  return englishContent
}

export function createProjects(locale: Locale) {
  const projects = englishContent.projects(new ProjectsData(locale))
  return locale === 'en' ? projects : contentFor(locale).projects(projects)
}

export function createProfile(locale: Locale, projects: ProjectsData) {
  return contentFor(locale).profile(new ProfileData(projects, locale))
}

export function createSolutions(locale: Locale, projects: ProjectsData) {
  return contentFor(locale).solutions(new SolutionsData(projects))
}

export function createCV(locale: Locale, profile: ProfileData, projects: ProjectsData) {
  return contentFor(locale).cv(new CVData(profile, projects, locale))
}
