import {ProjectRoute, ProjectRoutes} from '@/model/Data/ContentRoutes'
import {ProjectData} from '@/model/Data/ProjectData'
import {formatEngagementPeriods} from '@/model/content/DateFormat'
import {featuredProjectRoutes, projectCatalog} from '@/model/content/catalog/projects'
import type {Locale, ProjectCatalogEntry} from '@/model/content/Schema'
import {activeUi} from '@/model/content/active'
import {Locale as ActiveLocale} from '@/model/content/Locale'

export function projectHeroImage(project: Pick<ProjectCatalogEntry, 'heroImage' | 'images'>): string {
  return project.heroImage || (project.images || [])[0] || ''
}

const unique = <T>(items: T[]) => Array.from(new Set(items))

function uniqueBy<T>(items: T[], key: (item: T) => string) {
  const seen = new Set<string>()
  return items.filter(item => {
    const itemKey = key(item)
    if (seen.has(itemKey)) return false
    seen.add(itemKey)
    return true
  })
}

/**
 * Every project, in display order. A project that lists `subProjectRoutes`
 * groups its children and derives its clients, platforms, technologies, and
 * media from them; `featured` projects are the curated top-level list shown on
 * the projects index. There is no separate case-study collection: a case study
 * is simply a featured project whose content includes the structured narrative.
 */
export class ProjectsData extends Map<ProjectRoute, ProjectData> {

  readonly renetikMusicApps: ProjectData
  readonly portfolio: ProjectData
  readonly biolinq: ProjectData
  readonly sensoneoOlo: ProjectData
  readonly sodb2021: ProjectData
  readonly bmcharts: ProjectData
  readonly omwriter: ProjectData
  readonly propertyFarmer: ProjectData
  readonly motorkari: ProjectData
  readonly rcherzIOS: ProjectData
  readonly rcherzAndroid: ProjectData
  readonly rcherzScoring: ProjectData
  readonly renetikIOS: ProjectData
  readonly renetikAndroid: ProjectData
  readonly forceQuitMacOS: ProjectData
  readonly triadMarkiza: ProjectData
  readonly triadPromile: ProjectData
  readonly triadKompas: ProjectData
  readonly liveAgent: ProjectData
  readonly pap: ProjectData
  readonly taxicar: ProjectData
  readonly regiofood: ProjectData

  constructor(readonly locale: Locale = ActiveLocale.active) {
    super()
    projectCatalog.forEach(entry => this.set(entry.route, this.createProject(entry)))
    this.forEach(project => this.resolveGroupFacts(project))
    this.forEach(project => { project.heroImage = this.resolveHeroImage(project) })

    this.renetikMusicApps = this.require(ProjectRoutes.renetikMusicApps)
    this.portfolio = this.require(ProjectRoutes.portfolio)
    this.biolinq = this.require(ProjectRoutes.biolinq)
    this.sensoneoOlo = this.require(ProjectRoutes.sensoneoOlo)
    this.sodb2021 = this.require(ProjectRoutes.sodb2021)
    this.bmcharts = this.require(ProjectRoutes.bmcharts)
    this.omwriter = this.require(ProjectRoutes.omwriter)
    this.propertyFarmer = this.require(ProjectRoutes.propertyFarmer)
    this.motorkari = this.require(ProjectRoutes.motorkari)
    this.rcherzIOS = this.require(ProjectRoutes.rcherzIOS)
    this.rcherzAndroid = this.require(ProjectRoutes.rcherzAndroid)
    this.rcherzScoring = this.require(ProjectRoutes.rcherzScoring)
    this.renetikIOS = this.require(ProjectRoutes.renetikIOS)
    this.renetikAndroid = this.require(ProjectRoutes.renetikAndroid)
    this.forceQuitMacOS = this.require(ProjectRoutes.forceQuitMacOS)
    this.triadMarkiza = this.require(ProjectRoutes.triadMarkiza)
    this.triadPromile = this.require(ProjectRoutes.triadPromile)
    this.triadKompas = this.require(ProjectRoutes.triadKompas)
    this.liveAgent = this.require(ProjectRoutes.liveAgent)
    this.pap = this.require(ProjectRoutes.pap)
    this.taxicar = this.require(ProjectRoutes.taxicar)
    this.regiofood = this.require(ProjectRoutes.regiofood)
  }

  /** The curated top-level projects, in projects-index order. */
  get featured(): ProjectData[] {
    return featuredProjectRoutes.map(route => this.require(route))
  }

  /** Every route in {@link ProjectRoutes} resolves, so a miss is a coding error. */
  require(route: ProjectRoute): ProjectData {
    const project = this.get(route)
    if (!project) throw new Error(`Unknown project route: ${route}`)
    return project
  }

  findParentByRoute(route: ProjectRoute): ProjectData | undefined {
    return Array.from(this.values()).find(candidate => candidate.subProjectRoutes.includes(route))
  }

  subProjectsOf(project: ProjectData): ProjectData[] {
    return project.subProjectRoutes.map(route => this.require(route))
  }

  /**
   * An explicit header image wins; otherwise the first image the project can
   * reach, looking through its children before falling back to the portrait.
   */
  private resolveHeroImage(project: ProjectData): string {
    if (project.heroImage) return project.heroImage
    if (project.images.length) return project.images[0]
    const childImage = this.subProjectsOf(project)
      .map(child => this.resolveHeroImage(child))
      .find(Boolean)
    return childImage || '/images/profile/profile_1.jpg'
  }

  private createProject(entry: ProjectCatalogEntry): ProjectData {
    const finalPeriod = entry.periods[entry.periods.length - 1]
    const images = entry.images || []
    return {
      ...entry,
      title: '',
      subtitle: '',
      cardSummary: '',
      client: '',
      role: '',
      clients: entry.clients || [],
      periods: entry.periods,
      date: formatEngagementPeriods(entry.periods, this.locale, {presentLabel: activeUi().present}),
      platforms: entry.platforms || [],
      technologies: entry.technologies || [],
      paragraphs: [],
      problem: '',
      contribution: '',
      technicalWork: [],
      outcome: '',
      highlights: [],
      heroImage: entry.heroImage || '',
      images,
      imageAlts: images.map(() => ''),
      links: (entry.links || []).map(link => ({...link, tip: ''})),
      youtube: (entry.youtube || []).map(videoId => ({videoId})),
      subProjectRoutes: entry.subProjectRoutes || [],
      solutionRoutes: entry.solutionRoutes || [],
      startDate: entry.periods[0].startDate,
      endDate: finalPeriod.endDate,
      isCurrent: finalPeriod.isCurrent
    }
  }

  /**
   * A grouping project inherits what it does not declare itself, so its page
   * stays accurate as children are added without restating their facts.
   */
  private resolveGroupFacts(project: ProjectData) {
    const children = this.subProjectsOf(project)
    if (!children.length) return
    project.clients = project.clients.length ? project.clients : uniqueBy(
      children.flatMap(child => child.clients),
      client => `${client.id}:${client.url || ''}`
    )
    project.platforms = unique([...project.platforms, ...children.flatMap(child => child.platforms)])
    project.technologies = unique([...project.technologies, ...children.flatMap(child => child.technologies)])
    if (!project.images.length) {
      project.images = unique(children.flatMap(child => child.images))
      project.imageAlts = project.images.map(() => '')
    }
    if (!project.links.length) {
      project.links = uniqueBy(children.flatMap(child => child.links), link => link.url)
    }
    if (!project.youtube.length) {
      project.youtube = uniqueBy(children.flatMap(child => child.youtube), video => video.videoId)
    }
  }
}
