export const keepEnglishContent = <T>(data: T): T => data

interface MusicAppContentDetails {
  title: string
  subtitle: string
  paragraphs: string[]
  highlights: string[]
  imageAlts?: string[]
  hasFullVersion?: boolean
  hasStoreImage?: boolean
  hasWebsite?: boolean
}

const numberedImageAlts = (title: string, count: number) =>
  Array.from({length: count}, (_, index) => `${title} Android product screenshot ${index + 1}.`)
const reviewImageAlts = (title: string, count: number) =>
  Array.from({length: count}, (_, index) => `${title} customer review ${index + 1}.`)
const projectImageAlts = (title: string, count: number) =>
  Array.from({length: count}, (_, index) => `${title} screen ${index + 1}.`)

const musicApp = (details: MusicAppContentDetails): ProjectContent => ({
  title: details.title,
  subtitle: details.subtitle,
  cardSummary: details.subtitle,
  client: 'Renetik — independent product',
  role: 'Product designer, UX/UI designer, Android and audio engineer',
  paragraphs: [
    ...details.paragraphs,
    `I designed ${details.title} end to end: its product concept, music workflow, information architecture, interaction model, and visual interface. I then implemented the Android experience and took it through testing, release, iteration, and user support.`,
    `${details.title} is part of the Renetik Music Apps family and shares its Kotlin application foundations, native C++ audio engine, Firebase services, automated tests, and release workflow.`
  ],
  highlights: [
    'Independent product design and engineering from concept through Google Play release.',
    ...details.highlights
  ],
  linkTips: [
    ...(details.hasWebsite === false ? [] : ['User Guide']),
    'Free App',
    ...(details.hasFullVersion ? ['Full App Version'] : [])
  ],
  imageAlts: [
    `${details.title} feature artwork presenting its Android interface.`,
    ...(details.hasStoreImage ? [`${details.title} Google Play promotional screenshot.`] : []),
    ...(details.imageAlts || [])
  ]
})

