export function localizeProjects(data: ProjectsData) {
  data.forEach(project => {
    const content = projects[project.route]
    if (!content) throw new Error(`Missing English project content: ${project.route}`)
    Object.assign(project, content)
    project.links.forEach((link, index) => {
      link.tip = content.linkTips?.[index] || (
        link.title ||
        (link.kind === 'website' ? `Visit the ${content.title} website` : '') ||
        (link.kind === 'video' ? `Watch ${content.title} demos` : '') ||
        (link.kind === 'app' ? `Open the ${content.title} app listing` : '') ||
        (link.icon.includes('github') ? `View ${content.title} source on GitHub` : '') ||
        `Visit the ${content.title} resource`
      )
    })
    project.imageAlts = project.images.map((_, index) =>
      content.imageAlts?.[index] || `${content.title} screen or product visual ${index + 1}.`
    )
  })
  data.forEach(project => {
    const children = data.subProjectsOf(project)
    if (!children.length) return
    project.imageAlts = project.images.map((image, index) => {
      const child = children.find(candidate => candidate.images.includes(image))
      return child
        ? child.imageAlts[child.images.indexOf(image)]
        : project.imageAlts[index]
    })
    project.links.forEach(link => {
      const childLink = children.flatMap(child => child.links).find(candidate => candidate.url === link.url)
      if (childLink) link.tip = childLink.tip
    })
  })
  return data
}
